Rewrite the following GNU C++17 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
#define fi first
#define se second
using namespace std;

const int MX = 5500;
const long long INF = 1E9 + 7;

int n, m, k, c, d;
int u, v, mx, s = MX - 2, t = MX - 1, mf = 0, tr[MX];
long long ans = 0, dis[MX];
priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;

struct SEdge
{
    int v, c;
    int ind, cap;
};
vector<SEdge> adj[MX];

void add_edge(int u, int v, int c, int cap)
{
    int s1 = adj[u].size(), s2 = adj[v].size();
    adj[u].push_back((SEdge){v, c, s2, cap});
    adj[v].push_back((SEdge){u, -c, s1, 0});
}

void dijkstra()
{
    fill(dis, dis + MX, INF);
    pq.push({dis[s] = 0, s});
    while (!pq.empty())
    {
        pair<long long, int> u = pq.top();
        pq.pop();
        if (u.fi > dis[u.se])
            continue;
        for (SEdge &ed : adj[u.se])
        {
            if (ed.cap > 0 && dis[ed.v] > u.fi + ed.c)
            {
                tr[ed.v] = ed.ind;
                pq.push({dis[ed.v] = u.fi + ed.c, ed.v});
            }
        }
    }
}

void trace()
{
    int mx = k, v = t;
    while (v != s)
    {
        int u = adj[v][tr[v]].v, ind = adj[v][tr[v]].ind;
        mx = min(mx, adj[u][ind].cap);
        v = u;
    }
    mf += mx; ans += mx * dis[t];
    v = t;
    while (v != s)
    {
        int u = adj[v][tr[v]].v, ind = adj[v][tr[v]].ind;
        adj[v][tr[v]].cap += mx;
        adj[u][ind].cap -= mx;
        v = u;
    }
}

int at(int u, int t)
{
    return u + t * n;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> k >> c >> d;
    mx = n + k;
    for (int i = 0; i < k; i++)
    {
        cin >> u;
        add_edge(s, at(u, 0), 0, 1);
    }
    for (int i = 0; i <= mx; i++)
        add_edge(at(1, i), t, c * i, k);
    for (int i = 1; i <= n; i++)
        for (int j = 0; j < mx; j++)
            add_edge(at(i, j), at(i, j + 1), 0, k);
    while (m--)
    {
        cin >> u >> v;
        for (int i = 1; i <= k; i++)
            for (int j = 0; j < mx; j++)
            {
                add_edge(at(u, j), at(v, j + 1), d * (2 * i - 1), 1);
                add_edge(at(v, j), at(u, j + 1), d * (2 * i - 1), 1);
            }
    }
    while (mf < k)
    {
        dijkstra();
        trace();
    }
    cout << ans;
}

